import json,time
from pathlib import Path
import numpy as np
ROOT=Path('/app/output')
def call(cfg):
    response=ROOT/'response.json'
    response.unlink(missing_ok=True)
    (ROOT/'request.tmp').write_text(json.dumps(cfg));(ROOT/'request.tmp').rename(ROOT/'request.json')
    while not response.exists():time.sleep(.1)
    ans=json.loads(response.read_text())
    if 'error' in ans:raise RuntimeError(ans)
    print(ans,flush=True)
    return json.load(open(ans['path']+'/meta.json'))
def latest():
    p=ROOT/'latest.json'
    return json.load(open(p if p.exists() else '/app/runs/initial/meta.json'))
def move(q,name,steps=30,grip=-1):
    m=latest();q0=np.array(m['proprio']['now'][4:11]);acts=[]
    for t in np.linspace(0,1,steps):
        s=t*t*(3-2*t);acts.append([*(q0+(np.array(q)-q0)*s),grip,0,0,0,0,-1])
    acts.extend([[*q,grip,0,0,0,0,-1]]*10)
    return call({'op':'move','name':name,'actions':acts})
if __name__=='__main__':
    q0=np.array(latest()['proprio']['now'][4:11]);q=q0.copy();q[5]+=.15
    move(q,'cal1')
    q=q0.copy();q[4]+=.15
    move(q,'cal2')
    q=q0.copy();q[1]+=.15
    move(q,'cal3')
PY
