from geometry import *
from command import *
k=np.load('/app/output/kin.npz');RB=k['R'];b=k['b'];off=k['off']
DOWN=np.array([[2**-.5,-2**-.5,0],[-2**-.5,-2**-.5,0],[0,0,-1]])
def pose(q):
 T=fk(q);return RB@(T[:3,3]+T[:3,:3]@off)+b,RB@T[:3,:3]
def ik(p,R=DOWN,q0=None):
 if q0 is None:q0=np.array(latest()['proprio']['now'][4:11])
 def fun(q):
  pos,rot=pose(q)
  return np.r_[(pos-p)*3,Rot.from_matrix(R@rot.T).as_rotvec(),(q-q0)*.005]
 fit=least_squares(fun,q0,bounds=([-2.89,-1.76,-2.89,-3.06,-2.89,-.01,-2.89],[2.89,1.76,2.89,-.07,2.89,3.75,2.89]),max_nfev=500)
 pos,rot=pose(fit.x)
 print('IK',np.round(pos,4),'err',np.linalg.norm(pos-p),'q',np.round(fit.x,4),flush=True)
 assert np.linalg.norm(pos-p)<.008
 return fit.x

def goto(p,name,R=DOWN,steps=40,grip=-1):
 return move(ik(np.array(p),R),name,steps,grip)
if __name__=='__main__':
 import sys
 if sys.argv[1]=='hover':goto([2.507,-2.976,1.12],'steak_hover')
 elif sys.argv[1]=='reachtest':ik(np.array([2.955,-3.02,1.04]))
